public final class CompanionSummonModeService {
    private CompanionSummonModeService() {
    }

    public static MountCinematicMode modeFor(CompanionKind kind, CompanionMoveType moveType, boolean fallingRescue, boolean switchingMount, boolean transitionFromFlyingMount) {
        if (kind != CompanionKind.MOUNT) {
            return MountCinematicMode.NORMAL_SUMMON;
        }
        CompanionMoveType cinematicMoveType = CompanionSummonModeService.landPresentationMoveType(moveType);
        if (transitionFromFlyingMount) {
            return switch (cinematicMoveType) {
                default -> throw new IncompatibleClassChangeError();
                case CompanionMoveType.FLY -> MountCinematicMode.AIR_TO_FLY_SWITCH;
                case CompanionMoveType.WALK, CompanionMoveType.COMPANION -> MountCinematicMode.AIR_TO_WALK_SWITCH;
                case CompanionMoveType.SWIM -> MountCinematicMode.AIR_TO_SWIM_SWITCH;
            };
        }
        if (fallingRescue) {
            return switch (cinematicMoveType) {
                default -> throw new IncompatibleClassChangeError();
                case CompanionMoveType.FLY -> MountCinematicMode.FALL_RESCUE_FLY;
                case CompanionMoveType.WALK, CompanionMoveType.COMPANION -> MountCinematicMode.FALL_RESCUE_WALK;
                case CompanionMoveType.SWIM -> MountCinematicMode.FALL_RESCUE_SWIM;
            };
        }
        if (switchingMount) {
            return MountCinematicMode.MOUNT_SWITCH;
        }
        return MountCinematicMode.NORMAL_SUMMON;
    }

    public static CompanionMoveType landPresentationMoveType(CompanionMoveType moveType) {
        return moveType;
    }

    public static boolean isAirborneGroundRescue(ServerPlayer player, CompanionKind kind, CompanionMoveType moveType) {
        return kind == CompanionKind.MOUNT && player.m_20202_() == null && CompanionSummonModeService.isFallingFar(player) && CompanionSummonModeService.isGroundOrWater(moveType);
    }

    public static boolean isAirborneGroundVehicleRescue(ServerPlayer player, PlayerCompanionData data, CompanionKind kind, CompanionMoveType moveType) {
        Entity vehicle = player.m_20202_();
        return kind == CompanionKind.MOUNT && vehicle != null && !CompanionSummonModeService.isRegisteredBiologicalMount(data, vehicle) && CompanionSummonModeService.isFallingFar(player) && CompanionSummonModeService.isGroundOrWater(moveType);
    }

    public static boolean isRegisteredBiologicalMount(PlayerCompanionData data, Entity entity) {
        return entity instanceof LivingEntity && data.contains(CompanionKind.MOUNT, entity.m_20148_());
    }

    public static boolean isAirborneGroundMountSwitch(ServerPlayer player, CompanionKind kind, CompanionMoveType moveType) {
        Entity vehicle = player.m_20202_();
        return kind == CompanionKind.MOUNT && vehicle != null && CompanionSummonModeService.isFallingFar(player) && CompanionEntityClassifier.moveType(vehicle, CompanionKind.MOUNT) == CompanionMoveType.FLY && CompanionSummonModeService.isGroundOrWater(moveType);
    }

    public static boolean isAirborneGroundCompanionSummon(ServerPlayer player, CompanionKind kind, CompanionMoveType moveType) {
        Entity vehicle = player.m_20202_();
        return kind == CompanionKind.COMPANION && vehicle != null && CompanionSummonModeService.isFallingFar(player) && CompanionEntityClassifier.moveType(vehicle, CompanionKind.MOUNT) == CompanionMoveType.FLY && CompanionSummonModeService.isGroundOrWater(moveType);
    }

    private static boolean isFallingFar(ServerPlayer player) {
        return !player.m_20096_() && CompanionCinematicLandingService.distanceToGround(player) > 6.0;
    }

    private static boolean isGroundOrWater(CompanionMoveType moveType) {
        return moveType == CompanionMoveType.WALK || moveType == CompanionMoveType.SWIM;
    }
}

