        if (owner == null) {
            REQUESTS.remove(request.companionUuid, request);
            continue;
        }
        PlayerCompanionData data = CompanionDataService.data(owner);
        if (!data.contains(request.kind, request.companionUuid)) {
            REQUESTS.remove(request.companionUuid, request);
